-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- event-morning-ticket-holders
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal: event morning',
  'Today''s the day: Signal starts at 2pm',
  'Doors open at 1:30pm. How to get here, how check-in works and what the day looks like.',
  'ticket-purchasers',
  $nl$[{"id":"event-morning-ticket-holders-01","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-hero.jpg","alt":"A packed audience at a TEDxNewy event","widthPct":"full"},{"id":"event-morning-ticket-holders-02","type":"header","text":"Today's the day.","size":"lg"},{"id":"event-morning-ticket-holders-03","type":"text","html":"<p>Signal is today, and we can't wait to see you.</p><p><strong>Check-in is easy.</strong> Come with your name, your email or your ticket. However you arrive, we'll work out who you are.</p>"},{"id":"event-morning-ticket-holders-04","type":"header","text":"Where and when","size":"md"},{"id":"event-morning-ticket-holders-05","type":"text","html":"<p><strong>Saturday 24 October 2026</strong><br>Doors open at 1:30pm, event starts at 2:00pm<br>Conservatorium of Music, corner Laman Street and Auckland Street, Newcastle NSW 2300</p>"},{"id":"event-morning-ticket-holders-06","type":"button","label":"Get directions","href":"https://www.google.com/maps/search/?api=1&query=Newcastle+Conservatorium+of+Music","align":"center","theme":"ink","variant":"outline"},{"id":"event-morning-ticket-holders-07","type":"divider","style":"short","colour":"soft"},{"id":"event-morning-ticket-holders-08","type":"header","text":"Catch the light rail","size":"md"},{"id":"event-morning-ticket-holders-09","type":"text","html":"<p>Parking in the city can be busy on a Saturday, so we'd love you to leave the car at home and catch the light rail in.</p><p>Hop off at <strong>Civic</strong>, head towards King St, and walk up the hill on the right of Civic Park. The Conservatorium is up the hill, at the corner of Laman and Auckland Streets.</p><p>Plan your trip with the Transport for NSW trip planner.</p>"},{"id":"event-morning-ticket-holders-10","type":"button","label":"Plan your trip","href":"https://transportnsw.info/trip","align":"center","theme":"red","variant":"solid"},{"id":"event-morning-ticket-holders-11","type":"divider","style":"short","colour":"soft"},{"id":"event-morning-ticket-holders-12","type":"header","text":"Your day","size":"md"},{"id":"event-morning-ticket-holders-13","type":"columns","cols":[[{"id":"event-morning-ticket-holders-13-t","kind":"text","html":"<p><strong>1:30pm to 2:00pm</strong></p>"}],[{"id":"event-morning-ticket-holders-13-b","kind":"text","html":"<p><strong>Arrival and registration</strong><br>Doors open. Check in, grab your name badge and find your seat.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"event-morning-ticket-holders-14","type":"columns","cols":[[{"id":"event-morning-ticket-holders-14-t","kind":"text","html":"<p><strong>2:00pm to 3:30pm</strong></p>"}],[{"id":"event-morning-ticket-holders-14-b","kind":"text","html":"<p><strong>Session 1</strong><br>We open the event, followed by talks and performances.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"event-morning-ticket-holders-15","type":"columns","cols":[[{"id":"event-morning-ticket-holders-15-t","kind":"text","html":"<p><strong>3:30pm to 4:00pm</strong></p>"}],[{"id":"event-morning-ticket-holders-15-b","kind":"text","html":"<p><strong>Intermission</strong><br>Out in the foyer. Visit Activation Alley, play the Signal Side Quest and meet someone new.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"event-morning-ticket-holders-16","type":"columns","cols":[[{"id":"event-morning-ticket-holders-16-t","kind":"text","html":"<p><strong>4:00pm to 5:30pm</strong></p>"}],[{"id":"event-morning-ticket-holders-16-b","kind":"text","html":"<p><strong>Session 2</strong><br>A secret showcase, then the second round of talks.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"event-morning-ticket-holders-17","type":"columns","cols":[[{"id":"event-morning-ticket-holders-17-t","kind":"text","html":"<p><strong>5:30pm to 6:30pm</strong></p>"}],[{"id":"event-morning-ticket-holders-17-b","kind":"text","html":"<p><strong>Drinks hour</strong><br>Join us in the foyer to unpack the afternoon, and keep the conversations going.</p>"}]],"ratio":"33-66","valign":"top"},{"id":"event-morning-ticket-holders-18","type":"text","html":"<p>Your event day program, including the Signal Side Quest, is one tap away on your phone.</p>"},{"id":"event-morning-ticket-holders-19","type":"button","label":"Open the event day program","href":"https://tedxnewy.com.au/signal/links","align":"center","theme":"red","variant":"solid"},{"id":"event-morning-ticket-holders-20","type":"divider","style":"short","colour":"soft"},{"id":"event-morning-ticket-holders-21","type":"header","text":"Be kind to our team","size":"md"},{"id":"event-morning-ticket-holders-22","type":"text","html":"<p>Everyone on the TEDxNewy team is a volunteer, giving their time because they love this city and these ideas. We ask that you're kind and respectful to them, and to each other, at all times.</p><p>If you need help or support on the day, look for someone in a <strong>red shirt</strong>.</p>"},{"id":"event-morning-ticket-holders-23","type":"divider","style":"short","colour":"soft"},{"id":"event-morning-ticket-holders-24","type":"image","src":"https://tedxnewy.com.au/images/newsletter/partners-lockup.jpg","alt":"Our partners: University of Newcastle, Henderson, Hey Zomi, Frekl, Newy Digital and Sketch It Live","widthPct":100},{"id":"event-morning-ticket-holders-25","type":"header","text":"Thank you to our partners","size":"md"},{"id":"event-morning-ticket-holders-26","type":"text","html":"<p>Signal only happens because of the people and businesses who back it. Thank you to the University of Newcastle, Henderson, Hey Zomi, Frekl, Newy Digital, Sketch It Live and Hungerford Hill, to the venues offering event week deals, and to everyone who has helped make today a success.</p><p>See you this afternoon.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal: event morning'
);
